contracts/MockERC20.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

contract MockERC20 {
    string public name;
    string public symbol;
    uint8 public decimals;
    uint256 public totalSupply;
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;

    constructor(string memory _name, string memory _symbol, uint8 _decimals, uint256 _supply) {
        name = _name;
        symbol = _symbol;
        decimals = _decimals;
        totalSupply = _supply;
        balanceOf[msg.sender] = _supply;
    }

    function mint(address to, uint256 amount) external {
        balanceOf[to] += amount;
        totalSupply += amount;
    }

    function transfer(address to, uint256 amount) external returns (bool) {
        require(balanceOf[msg.sender] >= amount, "Bal");
        balanceOf[msg.sender] -= amount;
        balanceOf[to] += amount;
        return true;
    }

    function approve(address spender, uint256 amount) external returns (bool) {
        allowance[msg.sender][spender] = amount;
        return true;
    }

    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        require(allowance[from][msg.sender] >= amount, "Allow");
        require(balanceOf[from] >= amount, "Bal");
        allowance[from][msg.sender] -= amount;
        balanceOf[from] -= amount;
        balanceOf[to] += amount;
        return true;
    }
}

contracts/NexotiqDeal.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";

contract NexotiqDeal is ReentrancyGuard {
    address public factory;
    address public buyer;
    address public seller;
    /// @dev address(0) means native ETH, otherwise the ERC20 token (e.g. USDC/EURC on Arc)
    address public asset;

    string public title;
    string public description;
    uint256 public totalValue;
    uint256 public deadline;
    uint256 public riskScore;
    bool public protectionEnabled;

    enum DealStatus { Draft, Active, Completed, Disputed, Cancelled }
    enum MilestoneStatus { Pending, InProgress, Completed, Approved, Rejected }

    DealStatus public status;
    uint256 public currentMilestone;

    struct Milestone {
        string title;
        string description;
        uint256 amount;
        MilestoneStatus msStatus;
        uint256 dueDate;
        string evidenceHash;
        uint256 completedAt;
    }

    struct Dispute {
        address openedBy;
        string reason;
        string aiSummary;
        string aiRecommendation;
        bool buyerApproved;
        bool sellerApproved;
    }

    Milestone[] public milestones;
    Dispute public dispute;

    event MilestoneApproved(uint256 indexed milestoneId, uint256 amount, uint256 timestamp);
    event PaymentReleased(uint256 indexed milestoneId, uint256 amount, address indexed to);
    event DisputeOpened(address indexed openedBy, string reason);
    event DisputeResolved(string resolution);
    event DealCompleted(uint256 timestamp);
    event DealCancelled(uint256 timestamp);

    modifier onlyBuyer() { require(msg.sender == buyer, "Only buyer"); _; }
    modifier onlySeller() { require(msg.sender == seller, "Only seller"); _; }
    modifier onlyParty() { require(msg.sender == buyer || msg.sender == seller, "Only party"); _; }
    modifier inStatus(DealStatus s) { require(status == s, "Wrong status"); _; }
    modifier notDisputed() { require(status != DealStatus.Disputed, "Disputed"); _; }

    constructor() {
        factory = msg.sender;
    }

    function initialize(
        address _buyer,
        address _seller,
        string calldata _title,
        string calldata _description,
        uint256 _totalValue,
        uint256 _deadline,
        bool _protectionEnabled,
        address _asset
    ) external {
        require(factory == address(0) || msg.sender == factory, "Only factory");
        require(_buyer != address(0) && _seller != address(0), "Invalid address");
        require(_totalValue > 0, "Value must be > 0");

        factory = msg.sender;
        buyer = _buyer;
        seller = _seller;
        title = _title;
        description = _description;
        totalValue = _totalValue;
        deadline = _deadline;
        protectionEnabled = _protectionEnabled;
        asset = _asset;
        status = DealStatus.Active;
    }

    function _isNative() internal view returns (bool) { return asset == address(0); }

    function addMilestone(string calldata _title, string calldata _description, uint256 _amount, uint256 _dueDate) external onlyBuyer inStatus(DealStatus.Active) {
        milestones.push(Milestone(_title, _description, _amount, MilestoneStatus.Pending, _dueDate, "", 0));
    }

    function fundEscrow() external payable onlyBuyer inStatus(DealStatus.Active) {
        if (_isNative()) {
            require(msg.value == totalValue, "Send exact total value");
        } else {
            require(msg.value == 0, "Native ETH not expected");
            require(IERC20(asset).transferFrom(msg.sender, address(this), totalValue), "Transfer failed");
        }
    }

    function _release(address _to, uint256 _amount) internal {
        if (_isNative()) {
            (bool sent,) = _to.call{value: _amount}("");
            require(sent, "Transfer failed");
        } else {
            require(IERC20(asset).transfer(_to, _amount), "Token transfer failed");
        }
    }

    function startMilestone(uint256 _milestoneId) external onlySeller inStatus(DealStatus.Active) {
        require(_milestoneId < milestones.length, "Invalid milestone");
        require(milestones[_milestoneId].msStatus == MilestoneStatus.Pending, "Not pending");
        milestones[_milestoneId].msStatus = MilestoneStatus.InProgress;
    }

    function submitMilestone(uint256 _milestoneId, string calldata _evidenceHash) external onlySeller inStatus(DealStatus.Active) {
        require(_milestoneId < milestones.length, "Invalid milestone");
        require(milestones[_milestoneId].msStatus == MilestoneStatus.InProgress, "Not in progress");
        milestones[_milestoneId].msStatus = MilestoneStatus.Completed;
        milestones[_milestoneId].evidenceHash = _evidenceHash;
        milestones[_milestoneId].completedAt = block.timestamp;
    }

    function approveMilestone(uint256 _milestoneId) external onlyBuyer inStatus(DealStatus.Active) {
        require(_milestoneId < milestones.length, "Invalid milestone");
        require(milestones[_milestoneId].msStatus == MilestoneStatus.Completed, "Not completed");
        milestones[_milestoneId].msStatus = MilestoneStatus.Approved;

        uint256 amount = milestones[_milestoneId].amount;
        _release(seller, amount);

        emit MilestoneApproved(_milestoneId, amount, block.timestamp);
        emit PaymentReleased(_milestoneId, amount, seller);

        if (_milestoneId == milestones.length - 1) {
            status = DealStatus.Completed;
            emit DealCompleted(block.timestamp);
        } else {
            currentMilestone = _milestoneId + 1;
        }
    }

    function requestRevision(uint256 _milestoneId) external onlyBuyer inStatus(DealStatus.Active) {
        require(_milestoneId < milestones.length, "Invalid milestone");
        require(milestones[_milestoneId].msStatus == MilestoneStatus.Completed, "Not completed");
        milestones[_milestoneId].msStatus = MilestoneStatus.InProgress;
    }

    function openDispute(string calldata _reason) external onlyParty inStatus(DealStatus.Active) {
        status = DealStatus.Disputed;
        dispute = Dispute(msg.sender, _reason, "", "", false, false);
        emit DisputeOpened(msg.sender, _reason);
    }

    function updateDisputeAI(string calldata _summary, string calldata _recommendation) external {
        require(msg.sender == factory || msg.sender == buyer || msg.sender == seller, "Not authorized");
        require(status == DealStatus.Disputed, "Not disputed");
        dispute.aiSummary = _summary;
        dispute.aiRecommendation = _recommendation;
    }

    function approveDisputeResolution() external onlyParty {
        require(status == DealStatus.Disputed, "Not disputed");
        if (msg.sender == buyer) dispute.buyerApproved = true;
        if (msg.sender == seller) dispute.sellerApproved = true;
    }

    function executeDisputeResolution(string calldata _resolution) external {
        require(status == DealStatus.Disputed, "Not disputed");
        require(dispute.buyerApproved && dispute.sellerApproved, "Both must approve");

        if (keccak256(bytes(_resolution)) == keccak256(bytes("release_to_seller"))) {
            uint256 balance = address(this).balance;
            if (!_isNative()) balance = IERC20(asset).balanceOf(address(this));
            _release(seller, balance);
        } else if (keccak256(bytes(_resolution)) == keccak256(bytes("refund_buyer"))) {
            uint256 balance = address(this).balance;
            if (!_isNative()) balance = IERC20(asset).balanceOf(address(this));
            _release(buyer, balance);
        }

        status = DealStatus.Completed;
        emit DisputeResolved(_resolution);
        emit DealCompleted(block.timestamp);
    }

    function cancelDeal() external onlyBuyer inStatus(DealStatus.Active) {
        if (_isNative()) {
            uint256 balance = address(this).balance;
            if (balance > 0) {
                (bool sent,) = buyer.call{value: balance}("");
                require(sent, "Refund failed");
            }
        } else {
            uint256 balance = IERC20(asset).balanceOf(address(this));
            if (balance > 0) {
                require(IERC20(asset).transfer(buyer, balance), "Refund failed");
            }
        }
        status = DealStatus.Cancelled;
        emit DealCancelled(block.timestamp);
    }

    function escrowBalance() external view returns (uint256) {
        if (_isNative()) return address(this).balance;
        return IERC20(asset).balanceOf(address(this));
    }

    function getMilestones() external view returns (Milestone[] memory) { return milestones; }
    function getMilestoneCount() external view returns (uint256) { return milestones.length; }

    receive() external payable {}
}

contracts/NexotiqDirectory.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

contract NexotiqDirectory {
    struct Profile {
        address wallet;
        string name;
        string category;
        string[] skills;
        uint256 rate;
        string bio;
        bool available;
        uint256 createdAt;
        uint256 lastUpdated;
        uint256 completedDeals;
    }

    address[] private wallets;
    mapping(address => Profile) public profiles;
    mapping(address => bool) private exists;

    event ProfileCreated(address indexed wallet, string name, string category);
    event ProfileUpdated(address indexed wallet, string name, string category);
    event AvailabilityChanged(address indexed wallet, bool available);

    function _validate(string calldata _name, string calldata _category, string[] calldata _skills, uint256 _rate, string calldata _bio) private pure {
        bytes memory n = bytes(_name);
        require(n.length >= 2 && n.length <= 40, "Name 2-40 chars");
        require(bytes(_category).length <= 30, "Category too long");
        require(_skills.length <= 8, "Max 8 skills");
        require(_rate > 0, "Rate must be > 0");
        require(bytes(_bio).length <= 300, "Bio too long");
    }

    function registerProfile(
        string calldata _name,
        string calldata _category,
        string[] calldata _skills,
        uint256 _rate,
        string calldata _bio
    ) external {
        require(!exists[msg.sender], "Already registered");
        _validate(_name, _category, _skills, _rate, _bio);

        Profile storage p = profiles[msg.sender];
        p.wallet = msg.sender;
        p.name = _name;
        p.category = _category;
        for (uint256 i = 0; i < _skills.length; i++) {
            p.skills.push(_skills[i]);
        }
        p.rate = _rate;
        p.bio = _bio;
        p.available = true;
        p.createdAt = block.timestamp;
        p.lastUpdated = block.timestamp;

        wallets.push(msg.sender);
        exists[msg.sender] = true;

        emit ProfileCreated(msg.sender, _name, _category);
    }

    function updateProfile(
        string calldata _name,
        string calldata _category,
        string[] calldata _skills,
        uint256 _rate,
        string calldata _bio
    ) external {
        require(exists[msg.sender], "Not registered");
        _validate(_name, _category, _skills, _rate, _bio);

        Profile storage p = profiles[msg.sender];
        p.name = _name;
        p.category = _category;
        delete p.skills;
        for (uint256 i = 0; i < _skills.length; i++) {
            p.skills.push(_skills[i]);
        }
        p.rate = _rate;
        p.bio = _bio;
        p.lastUpdated = block.timestamp;

        emit ProfileUpdated(msg.sender, _name, _category);
    }

    function setAvailable(bool _available) external {
        require(exists[msg.sender], "Not registered");
        profiles[msg.sender].available = _available;
        emit AvailabilityChanged(msg.sender, _available);
    }

    function incrementCompletedDeals(address _wallet) external {
        require(exists[_wallet], "Not registered");
        profiles[_wallet].completedDeals += 1;
    }

    function getProfile(address _wallet) external view returns (Profile memory) {
        return profiles[_wallet];
    }

    function isRegistered(address _wallet) external view returns (bool) {
        return exists[_wallet];
    }

    function getProfileCount() external view returns (uint256) {
        return wallets.length;
    }

    function getProfileAt(uint256 _index) external view returns (Profile memory) {
        return profiles[wallets[_index]];
    }

    function getAllProfiles() external view returns (Profile[] memory) {
        Profile[] memory all = new Profile[](wallets.length);
        for (uint256 i = 0; i < wallets.length; i++) {
            all[i] = profiles[wallets[i]];
        }
        return all;
    }
}

contracts/NexotiqFactory.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "./NexotiqDeal.sol";
import "@openzeppelin/contracts/proxy/Clones.sol";

contract NexotiqFactory {
    using Clones for address;

    address public dealImplementation;
    address public reputationContract;

    address public feeCollector;
    uint256 public feeBps = 50; // 0.5%

    struct DealInfo {
        address dealAddress;
        address buyer;
        address seller;
        uint256 totalValue;
        uint256 createdAt;
        bool active;
        address asset;
    }

    DealInfo[] public deals;
    mapping(address => uint256[]) public userDealIndices;

    event DealCreated(address indexed dealAddress, address indexed buyer, address indexed seller, uint256 value, uint256 dealId);
    event FeeUpdated(uint256 oldFee, uint256 newFee);

    constructor(address _dealImplementation, address _reputationContract, address _feeCollector) {
        dealImplementation = _dealImplementation;
        reputationContract = _reputationContract;
        feeCollector = _feeCollector;
    }

    function createDeal(
        address _seller,
        string calldata _title,
        string calldata _description,
        uint256 _totalValue,
        uint256 _deadline,
        bool _protectionEnabled,
        address _asset
    ) external returns (address) {
        require(_seller != address(0), "Invalid seller");
        require(_totalValue > 0, "Value must be > 0");

        address payable dealAddr = payable(dealImplementation.clone());
        NexotiqDeal(dealAddr).initialize(msg.sender, _seller, _title, _description, _totalValue, _deadline, _protectionEnabled, _asset);

        deals.push(DealInfo(dealAddr, msg.sender, _seller, _totalValue, block.timestamp, true, _asset));
        uint256 dealId = deals.length - 1;
        userDealIndices[msg.sender].push(dealId);
        userDealIndices[_seller].push(dealId);

        emit DealCreated(dealAddr, msg.sender, _seller, _totalValue, dealId);
        return dealAddr;
    }

    function getDealCount() external view returns (uint256) { return deals.length; }
    function getDeal(uint256 _index) external view returns (DealInfo memory) { return deals[_index]; }
    function getUserDeals(address _user) external view returns (DealInfo[] memory) {
        uint256[] memory indices = userDealIndices[_user];
        DealInfo[] memory userDeals = new DealInfo[](indices.length);
        for (uint256 i = 0; i < indices.length; i++) {
            userDeals[i] = deals[indices[i]];
        }
        return userDeals;
    }

    function updateDealImplementation(address _newImpl) external {
        require(msg.sender == feeCollector, "Not authorized");
        dealImplementation = _newImpl;
    }

    function updateFee(uint256 _newFeeBps) external {
        require(msg.sender == feeCollector, "Not authorized");
        emit FeeUpdated(feeBps, _newFeeBps);
        feeBps = _newFeeBps;
    }
}

contracts/NexotiqProtection.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

contract NexotiqProtection {
    address public factory;
    address public feeCollector;

    struct Coverage {
        address dealAddress;
        address buyer;
        uint256 coverageAmount;
        uint256 premium;
        uint256 riskScore;
        bool active;
        bool claimed;
    }

    mapping(address => Coverage) public coverages;
    uint256 public totalPremiums;
    uint256 public totalPayouts;

    event CoverageCreated(address indexed deal, address indexed buyer, uint256 amount, uint256 premium);
    event ClaimFiled(address indexed deal, uint256 amount);
    event ClaimResolved(address indexed deal, bool approved, uint256 payout);

    modifier onlyFactory() { require(msg.sender == factory, "Only factory"); _; }

    constructor(address _factory, address _feeCollector) {
        factory = _factory;
        feeCollector = _feeCollector;
    }

    function createCoverage(
        address _dealAddress,
        address _buyer,
        uint256 _coverageAmount,
        uint256 _riskScore
    ) external onlyFactory returns (uint256 premium) {
        premium = (_coverageAmount * _riskScore) / 10000;
        if (premium < 0.001 ether) premium = 0.001 ether;

        coverages[_dealAddress] = Coverage(_dealAddress, _buyer, _coverageAmount, premium, _riskScore, true, false);
        totalPremiums += premium;

        emit CoverageCreated(_dealAddress, _buyer, _coverageAmount, premium);
        return premium;
    }

    function payPremium() external payable {
        require(msg.value > 0, "Premium must be > 0");
    }

    function fileClaim(address _dealAddress) external {
        Coverage storage cov = coverages[_dealAddress];
        require(cov.active, "No active coverage");
        require(!cov.claimed, "Already claimed");
        cov.claimed = true;
        emit ClaimFiled(_dealAddress, cov.coverageAmount);
    }

    function resolveClaim(address _dealAddress, bool _approved) external onlyFactory {
        Coverage storage cov = coverages[_dealAddress];
        require(cov.claimed, "No claim filed");
        require(cov.active, "Not active");

        if (_approved) {
            uint256 payout = cov.coverageAmount;
            require(address(this).balance >= payout, "Insufficient pool");
            (bool sent,) = cov.buyer.call{value: payout}("");
            require(sent, "Payout failed");
            totalPayouts += payout;
        }

        cov.active = false;
        emit ClaimResolved(_dealAddress, _approved, _approved ? cov.coverageAmount : 0);
    }

    function withdrawPremiums() external {
        require(msg.sender == feeCollector, "Not authorized");
        uint256 balance = address(this).balance;
        (bool sent,) = feeCollector.call{value: balance}("");
        require(sent, "Withdraw failed");
    }

    function getCoverage(address _dealAddress) external view returns (Coverage memory) {
        return coverages[_dealAddress];
    }
}

