// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

contract NexotiqRegistry {
    address public owner;

    mapping(address => string) public addressToUsername;
    mapping(bytes32 => address) public usernameToAddress;

    event UsernameRegistered(address indexed user, string username);
    event UsernameUpdated(address indexed user, string oldUsername, string newUsername);

    modifier onlyOwner() { require(msg.sender == owner, "Not owner"); _; }

    constructor() {
        owner = msg.sender;
    }

    function isUsernameTaken(string calldata _username) external view returns (bool) {
        bytes32 key = keccak256(abi.encodePacked(_username));
        return usernameToAddress[key] != address(0);
    }

    function register(string calldata _username) external {
        bytes memory b = bytes(_username);
        require(b.length >= 3 && b.length <= 32, "3-32 chars");
        bytes32 key = keccak256(abi.encodePacked(_username));
        require(usernameToAddress[key] == address(0), "Username taken");
        require(bytes(addressToUsername[msg.sender]).length == 0, "Already registered");

        addressToUsername[msg.sender] = _username;
        usernameToAddress[key] = msg.sender;

        emit UsernameRegistered(msg.sender, _username);
    }

    function getUsername(address _user) external view returns (string memory) {
        return addressToUsername[_user];
    }

    function getAddress(string calldata _username) external view returns (address) {
        return usernameToAddress[keccak256(abi.encodePacked(_username))];
    }

    function updateUsername(string calldata _newUsername) external {
        bytes memory b = bytes(_newUsername);
        require(b.length >= 3 && b.length <= 32, "3-32 chars");
        bytes32 newKey = keccak256(abi.encodePacked(_newUsername));
        require(usernameToAddress[newKey] == address(0), "Username taken");

        string memory old = addressToUsername[msg.sender];
        require(bytes(old).length > 0, "Not registered");
        bytes32 oldKey = keccak256(abi.encodePacked(old));

        usernameToAddress[oldKey] = address(0);
        addressToUsername[msg.sender] = _newUsername;
        usernameToAddress[newKey] = msg.sender;

        emit UsernameUpdated(msg.sender, old, _newUsername);
    }
}

contracts/NexotiqReputation.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

contract NexotiqReputation {
    address public factory;

    struct Reputation {
        uint256 totalDeals;
        uint256 successfulDeals;
        uint256 failedDeals;
        uint256 totalVolume;
        uint256 disputesOpened;
        uint256 disputesWon;
        uint256 score;
        bool exists;
    }

    mapping(address => Reputation) public reputations;
    mapping(address => address[]) public verifiers;

    event ReputationUpdated(address indexed user, uint256 newScore);
    event DealRecorded(address indexed user, bool success, uint256 volume);

    modifier onlyFactory() { require(msg.sender == factory, "Only factory"); _; }

    constructor(address _factory) {
        factory = _factory;
    }

    function recordDealCompletion(address _user, bool _success, uint256 _volume) external onlyFactory {
        Reputation storage rep = reputations[_user];
        if (!rep.exists) {
            rep.exists = true;
            rep.score = 85;
        }

        rep.totalDeals++;
        rep.totalVolume += _volume;

        if (_success) {
            rep.successfulDeals++;
        } else {
            rep.failedDeals++;
        }

        _recalculateScore(_user);
    }

    function recordDispute(address _user, bool _won) external onlyFactory {
        Reputation storage rep = reputations[_user];
        if (!rep.exists) { rep.exists = true; rep.score = 85; }
        rep.disputesOpened++;
        if (_won) rep.disputesWon++;
        _recalculateScore(_user);
    }

    function _recalculateScore(address _user) internal {
        Reputation storage rep = reputations[_user];
        uint256 score = 85;

        if (rep.totalDeals > 0) {
            uint256 successRate = (rep.successfulDeals * 100) / rep.totalDeals;
            score = successRate;

            if (rep.totalVolume > 0) {
                uint256 volumeBonus = rep.totalVolume / 1000 ether;
                if (volumeBonus > 10) volumeBonus = 10;
                score += volumeBonus;
            }

            if (rep.disputesOpened > 0) {
                uint256 disputePenalty = (rep.disputesOpened * 5);
                if (disputePenalty > score / 2) disputePenalty = score / 2;
                score -= disputePenalty;
            }
        }

        if (score > 100) score = 100;
        rep.score = score;
        emit ReputationUpdated(_user, score);
    }

    function getReputation(address _user) external view returns (Reputation memory) {
        if (!reputations[_user].exists) {
            return Reputation(0, 0, 0, 0, 0, 0, 85, false);
        }
        return reputations[_user];
    }

    function addVerifier(address _verifier) external {
        require(msg.sender == factory, "Only factory");
        verifiers[msg.sender].push(_verifier);
    }
}

